import React from 'react';
import '../App.css';

const Topbar = ({ user, onLogout }) => {
    return (
        <div className="topbar">
            <span className="me-3 fw-bold">Welcome, {user.name} ({user.role})</span>
            <button className="btn btn-dark btn-sm rounded-0" onClick={onLogout}>Logout</button>
        </div>
    );
};

export default Topbar;
